import {THEMES,PEOPLE,esc,initials,timeAgo,loadDemo,saveDemo,toggle,addPost,addMessage,addComment,updateProfile,newCircle,cleanText,parseRoute,validateCatalogue,clone} from './core.mjs';
import {ORIGINALS,Player} from './audio.mjs';
import {client,Service,profile as memberProfile} from './backend.mjs';
import {TOPICS,preferences,upgradeSample,topicFor,personTopic,validPhoto,validPoll,createMoment,vote,editMoment,removeMoment,restoreMoment,recordActivity,selectFeed,feedReason,safeLink,searchLocal} from './social.mjs';
import {preparePhoto} from './media.mjs';
import {ARTWORK,IDENTITY_ART,artworkSource,artworkImage,identityArtwork,topicArtwork,circleArtwork,coverArtwork,albumArtwork,originalGatheringImage} from './artwork.mjs';
import {SKINS,skinById,readSpace,saveSpace,topMates,toggleMate,skinStyle,mountVisuals} from './combined.mjs';
const app=document.querySelector('#app'),dialog=document.querySelector('#dialog'),audio=document.querySelector('#audio');
const storage={getItem:k=>{try{return localStorage.getItem(k);}catch{return null;}},setItem:(k,v)=>localStorage.setItem(k,v),removeItem:k=>localStorage.removeItem(k)};
const state={...parseRoute(location.hash),mode:'demo',demo:upgradeSample(loadDemo(storage)),member:null,service:null,sb:null,epoch:0,loading:false,error:'',feed:'all',people:'all',query:'',music:'original',musicQuery:'',community:[],communityState:'idle',uploads:[],comments:new Set(),drafts:{},liked:[],saved:[],favorites:[],searchResults:[],visitor:null,busy:new Set(),localPrefs:preferences(),postKind:'words',photo:null,reply:null,chatQuery:'',removed:null,searchQuery:''};
let worldView=null,visualCleanup=null;
const studio={selected:'',category:'All',query:''};
const paths={home:'M3 10 12 3l9 7v11h-6v-7H9v7H3Z',people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8M22 21v-2a4 4 0 0 0-3-3.9M16 3a4 4 0 0 1 0 8',chat:'M21 11a8 8 0 0 1-8 8H7l-5 3 2-6a8 8 0 1 1 17-5ZM7 10h10M7 14h6',music:'M9 18V5l12-2v13M9 8l12-2M9 18a3 2 0 1 1-6 0 3 2 0 0 1 6 0M21 16a3 2 0 1 1-6 0 3 2 0 0 1 6 0',space:'M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8M4 22v-2a8 8 0 0 1 16 0v2',arrow:'M5 12h14M13 6l6 6-6 6',arrowUp:'M6 18 18 6M6 6h12v12',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z',save:'M5 3h14v19l-7-5-7 5Z',search:'M21 21l-6-6M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',plus:'M12 4v16M4 12h16',close:'m6 6 12 12M6 18 18 6',check:'m5 12 4 4L19 6',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1Z',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',image:'M3 3h18v18H3ZM3 16l5-5 4 4 3-3 6 6M16 7h.01',play:'m8 4 12 8-12 8Z',pause:'M8 5v14M16 5v14',next:'m5 5 11 7-11 7ZM20 5v14',previous:'m19 5-11 7 11 7ZM4 5v14',volume:'M11 4 5 9H2v6h3l6 5ZM15 8a5 5 0 0 1 0 8M18 5a9 9 0 0 1 0 14',repeat:'m18 2 4 4-4 4M2 11V8a2 2 0 0 1 2-2h18M6 22l-4-4 4-4M22 13v3a2 2 0 0 1-2 2H2',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v2M12 20v2M2 12h2M20 12h2M5 5l1 1M18 18l1 1M5 19l1-1M18 6l1-1',back:'m14 6-6 6 6 6',leaf:'M20 3C5 3 2 10 6 17s15 2 14-14ZM4 21l11-11',share:'M12 16V2m-5 5 5-5 5 5M5 12H3v9h18v-9h-2',download:'M12 3v12m-5-5 5 5 5-5M3 16v5h18v-5'};
const icon=(name,cls='')=>`<svg class="ico ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.sun}"/></svg>`;
const btn=(label,action,value='',extra='')=>`<button type="button" class="btn ${extra}" data-action="${action}" data-value="${esc(value)}">${label}</button>`;
const avatar=(p,extra='')=>{const key=identityArtwork(p,state.mode);return `<span class="avatar ${['peach','lavender','sage','yellow','blue','rose'].includes(p?.color)?p.color:'sage'} ${extra}" aria-hidden="true">${key?artworkImage(key,{decorative:true}):esc(p?.emoji||initials(p?.name))}</span>`;};
const sampleLabel=p=>state.mode==='demo'&&PEOPLE.some(x=>x.id===p?.id)?'<span class="fictional-badge">Fictional sample</span>':'';
const brand=(mobile=false)=>`<a class="brand ${mobile?'mobile-brand':''}" href="#${state.page==='welcome'?'welcome':'home'}" aria-label="Sota Kece home"><img src="./icon.svg" alt="" width="36" height="36"><span>Sota Kece<small>a little closer</small></span></a>`;
const me=()=>state.mode==='member'?state.member?.me||{id:state.service?.user?.id,name:'Your space',handle:'',emoji:'☀️',theme:'lagoon'}:state.demo.profile;
const person=id=>id==='you'||id===me().id?me():PEOPLE.find(p=>p.id===id)||state.member?.people?.find(p=>p.id===id)||{id,name:'Member',emoji:'🌺',color:'sage'};
const data=()=>state.mode==='member'?state.member||{}:state.demo;
const posts=()=>data().posts||[];
const circles=()=>data().circles||[];
const saved=()=>state.mode==='demo'?state.demo.saved:state.saved;
const likes=()=>state.mode==='demo'?state.demo.liked:state.liked;
const favorites=()=>state.mode==='demo'?state.demo.favorites:state.favorites;
function persist(){if(state.mode==='demo'){state.unsaved=!saveDemo(storage,state.demo);if(state.unsaved)toast('Your changes work here.');}}
let toastTimer;function toast(message){const el=document.querySelector('#toast');el.textContent=message+(state.mode==='demo'&&state.unsaved?' This browser could not save your changes; keep this tab open and download your sample data in Settings.':'');el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3500);}
function go(page,arg=''){const next='#'+page+(arg?'/'+encodeURIComponent(arg):'');if(location.hash===next)loadPage();else location.hash=next;}
function pageHeader(kicker,title,description='',action=''){return `<header class="page-head"><div><span class="eyebrow">${kicker}</span><h1 tabindex="-1" id="page-title">${title}</h1>${description?`<p>${description}</p>`:''}</div>${action||`<span class="date">${new Intl.DateTimeFormat('en',{weekday:'long',month:'short',day:'numeric'}).format(new Date())}</span>`}</header>`;}
function empty(title,text,action=''){return `<section class="empty">${icon('leaf')}<h2>${esc(title)}</h2><p>${esc(text)}</p>${action}</section>`;}
function art(kind){return `<figure class="post-artwork">${artworkImage(({craft:'making',island:'outside',music:'music'})[kind]||'hero')}</figure>`;}
function album(track,small=false){return `<span class="album-art ${small?'small':''}" aria-hidden="true">${artworkImage(albumArtwork(track),{decorative:true})}</span>`;}
const navItems=[['home','Home','home'],['people','People','people'],['talanoa','Talanoa','chat'],['music','Music','music'],['space','My space','space']];
function shell(content){const p=me();return `<aside class="rail">${brand()}<span class="eyebrow">Your little corner</span><nav class="main-nav" aria-label="Main navigation">${navItems.map(([key,label,ico])=>`<a href="#${key}" ${(state.page===key||['discover','world'].includes(state.page)&&key==='people'||state.page==='studio'&&key==='space')?'aria-current="page"':''}>${icon(ico)}<span>${label}</span>${key==='talanoa'?'<i class="nav-dot" aria-hidden="true"></i>':''}</a>`).join('')}</nav><div class="rail-extras"><a href="#world">${icon('sun')} Your world in 3D</a><a href="#studio">${icon('settings')} Room Studio <span>94</span></a></div><div class="rail-foot"><div class="mini-mark">✳</div><p>Far apart.<br>Still together.</p><a class="rail-profile" href="#space">${avatar(p)}<span><strong>${esc(p.name)}</strong><small>${state.mode==='demo'?'Your sample space':'@'+esc(p.handle)}</small></span></a></div></aside><div class="app-body"><header class="topbar"><span class="crumb">A little closer to the people who matter.</span>${brand(true)}<div class="tools"><button class="icon-btn" data-action="search" aria-label="Search your community">${icon('search')}</button><span class="mode-badge"><i class="dot"></i><b>${state.mode==='demo'?'Sample community':'Your community'}</b></span>${state.mode==='demo'?btn('Sign in','auth','','small auth'):''}<button class="icon-btn" data-action="activity" aria-label="View activity">${icon('bell')}</button><a href="#settings" class="icon-btn settings" aria-label="Settings">${icon('settings')}</a></div></header><main id="main" class="main">${state.mode==='demo'?'<div class="sample-bar"><span>AI-generated fictional people. <span class="extra">Sample activity </span>stays on this device.</span><button data-action="about-demo">About this preview</button></div>':''}${content}</main></div>`;}
function welcome(){return `<header class="welcome-header">${brand()}<nav aria-label="Explore"><a href="#people">People</a><a href="#talanoa">Talanoa</a><a href="#music">Music</a><a href="#space">Your space</a></nav>${btn('Sign in '+icon('arrowUp'),'auth','','small')}</header><main id="main" class="welcome"><section class="landing-hero"><div class="landing-copy"><span class="eyebrow">Fiji roots. Open hearts. Everywhere.</span><h1>Your people.<br>Your rhythm.<br><em>Your place.</em></h1><p>Some connections feel like coming home. A space for good conversations, shared songs and the little things that make you, you.</p><div class="row wrap"><a class="btn primary" href="#home">Come on in ${icon('arrow')}</a>${btn('Make it yours','auth-up','','flat')}</div><p class="quiet-note">Take a look around the sample community.<br>No account needed. Just a little curiosity.</p></div><div class="hero-scene">${originalGatheringImage('hero-art')}<span class="scene-caption">A LITTLE CLOSER TO HOME</span><span class="sunburst" aria-hidden="true">✳</span><div class="float-note"><div class="row">${avatar(PEOPLE[0])}<span>A little note from Ani<br><small>Sample community</small></span></div><p>There’s room for you here.</p></div><button class="float-player" data-action="play" data-value="lagoon" aria-label="Play Sea glass, an original Sota Sessions instrumental"><span class="cover-thumb">${artworkImage('album-lagoon',{decorative:true})}</span><span><small>SOTA SESSIONS · ORIGINAL</small><strong>Sea glass</strong></span><span class="round-play">${icon('play')}</span></button></div></section><section class="welcome-band"><span class="serif">A place to belong.<br>A little more you.</span><div class="avatar-stack">${PEOPLE.slice(0,4).map(p=>avatar(p)).join('')}</div><p>Less noise. More of the people, conversations and moments you choose to keep close.</p></section><div class="section-title"><div><span class="eyebrow">Made for the things that matter</span><h2>Life happens between us.</h2></div></div><section class="feature-grid"><article class="feature-card sage">${artworkImage('culture',{className:'feature-art'})}<h2>Good people.<br>Close by.</h2><p>Find a familiar face, catch a little moment and make time for your people.</p><a class="text-link" href="#people">Meet the community ↗</a></article><article class="feature-card peach">${artworkImage('hero',{className:'feature-art'})}<h2>Pull up<br>a seat.</h2><p>A good talanoa starts with hello. Bring your friends into a circle of your own.</p><a class="text-link" href="#talanoa">Explore the circles ↗</a></article><article class="feature-card lavender">${artworkImage('music',{className:'feature-art'})}<h2>Find your<br>kind of sound.</h2><p>Original little instrumentals, community favourites and the music you bring.</p><a class="text-link" href="#music">Press play ↗</a></article></section>${combinedFeatures()}<section class="welcome-end"><span class="eyebrow">Come exactly as you are</span><h2>Your little corner<br>of a bigger world.</h2><a class="btn primary" href="#space">Explore your space ${icon('arrow')}</a></section><footer class="footer"><span>Sota Kece · a little closer.<br>Original artwork. Familiar island roots.</span><button data-action="privacy" class="text-link">Your privacy</button></footer></main>`;}
function postCard(p){const who=p.person||person(p.author),own=p.author===me().id,open=state.comments.has(p.id),liked=likes().includes(p.id)||p.liked,topic=TOPICS.find(t=>t.id===topicFor(p)),isSample=state.mode==='demo';return `<article class="card feed-post" data-post="${esc(p.id)}"><div class="post-context">${isSample?esc(feedReason(p,prefs(),friendIds(),me().id)):'Shared with friends'}${p.id===me().pinned?' · Pinned in My space':''}</div><div class="row">${avatar(who)}<div class="grow"><button class="post-name" data-action="visit" data-value="${esc(who.handle||p.author)}">${esc(who.name)}</button>${sampleLabel(who)}<div class="post-meta">${timeAgo(p.createdAt)}${p.edited?' · Edited':''}${topic?` · ${esc(topic.label)}`:''}</div></div><button class="icon-btn ${saved().includes(p.id)?'on':''}" data-action="save-post" data-value="${esc(p.id)}" aria-label="${saved().includes(p.id)?'Unsave':'Save'} this moment" aria-pressed="${saved().includes(p.id)}">${icon('save')}</button><button class="icon-btn" data-action="post-menu" data-value="${esc(p.id)}" aria-label="Options for this moment">•••</button></div><p class="post-body">${esc(p.text)}</p>${validPhoto(p.photo)?`<figure class="moment-photo"><img src="${esc(p.photo.src)}" alt="${esc(p.photo.alt)}" loading="lazy"><figcaption>${esc(p.photo.alt)}</figcaption></figure>`:['craft','island','music'].includes(p.art)?art(p.art):''}${validPoll(p.poll)?pollMarkup(p):''}<div class="post-actions"><button class="${liked?'on':''}" data-action="like" data-value="${esc(p.id)}" aria-pressed="${liked}" aria-label="${liked?'Liked':'Like'} this moment">${icon('heart')} ${p.likes+(likes().includes(p.id)?1:0)||'Like'}</button>${isSample?`<button data-action="comments" data-value="${esc(p.id)}" aria-expanded="${open}">${icon('chat')} ${p.comments?.length||'Reply'}</button>`:''}${own?'<span class="last stamp">Your moment</span>':`<button class="last" data-action="visit" data-value="${esc(who.handle||p.author)}">Visit space ${icon('arrowUp')}</button>`}</div>${open?`<div class="comments">${(p.comments||[]).map(c=>`<div class="comment">${avatar(person(c.author))}<div><b>${esc(person(c.author).name)}</b><p>${esc(c.text)}</p></div></div>`).join('')}${p.replyMode==='off'?'<p class="muted">Replies are closed for this moment.</p>':`<form data-form="comment" data-id="${esc(p.id)}" class="comment-form"><label class="sr-only" for="comment-${esc(p.id)}">Write a reply</label><input id="comment-${esc(p.id)}" name="text" maxlength="300" placeholder="Leave a little reply…" required value="${esc(state.drafts['comment-'+p.id]||'')}" data-draft="comment-${esc(p.id)}"><button class="btn small" type="submit">Send</button></form>`}</div>`:''}</article>`;}
function friendAside(){const friends=state.mode==='demo'?PEOPLE.filter(p=>state.demo.friends.includes(p.id)):(data().people||[]);return `<aside class="aside"><section class="card"><div class="row between"><h3>Your people</h3><a href="#people" class="stamp">See all ↗</a></div>${friends.slice(0,4).map(p=>`<button class="person" data-action="visit" data-value="${esc(p.handle)}">${avatar(p)}<span class="grow"><strong>${esc(p.name)}</strong><small>${state.mode==='demo'?esc(p.interest):'@'+esc(p.handle)}</small></span></button>`).join('')||'<p class="muted">Your people will appear here.</p>'}</section><section class="card soft"><span class="eyebrow">A little thought</span><p class="quote">“The best part of a place is who you share it with.”</p><span class="quote-credit">A note from Sota Kece</span></section><section class="card"><h3>Your circles</h3>${circles().filter(c=>c.joined).slice(0,3).map(c=>`<button class="mini-circle" data-action="open-circle" data-value="${esc(c.id)}">${circleBadge(c)}<span><b>${esc(c.name)}</b><small>${c.members} ${c.members===1?'member':'members'}</small></span></button>`).join('')}<a href="#talanoa" class="text-link">Pull up a seat ↗</a></section><div class="aside-foot">Sota Kece · a little closer<br><button data-action="privacy">Your privacy</button> · <button data-action="about-demo">About this experience</button></div></aside>`;}
function home(){const friends=friendIds(),feed=selectFeed(posts(),prefs(),state.feed,{owner:me().id,friends,saved:saved()});return `${pageHeader('A little closer, every day.','Good to have you here.',"Your people. Your interests. Your own pace.",`<a class="btn small" href="#discover">${icon('search')} Discover</a>`)}<div class="columns"><div><section class="daily-note original-home"><figure>${originalGatheringImage()}<figcaption>Original Sota Kece artwork · illustrative people</figcaption></figure><div><span class="eyebrow">A thought for today</span><h2>Make room for the little things.</h2><p>What’s one thing you’d like to remember?</p></div></section><nav class="home-quick-links" aria-label="Make it your own"><a href="#studio">${icon('settings')}<span><b>Room Studio ↗</b><small>94 ways to feel at home</small></span></a><a href="#world">${icon('sun')}<span><b>Your world ↗</b><small>Your people, in 3D</small></span></a><a href="#music">${icon('music')}<span><b>Music & visuals ↗</b><small>A soundtrack to your day</small></span></a></nav><div class="card composer">${avatar(me())}<button class="compose-prompt" data-action="compose">What’s a little good in your day?</button><button class="icon-btn" data-action="compose" aria-label="Share a moment">${icon('plus')}</button></div>${state.mode==='demo'?`<div class="composer-tools">${btn(icon('image')+' Photo','compose-kind','photo','flat small')}${btn('◔ Ask your people','compose-kind','poll','flat small')}${btn('✳ Choose your interests','interests','','flat small')}</div>`:''}<div class="feed-toolbar"><div class="filter-row" role="group" aria-label="Filter moments">${[['all','For you'],['following','Your people'],['latest','Latest'],['mine','My moments'],['saved','Saved']].map(([v,l])=>`<button class="chip ${state.feed===v?'on':''}" data-action="feed-filter" data-value="${v}" aria-pressed="${state.feed===v}">${l}</button>`).join('')}</div><button class="text-link" data-action="feed-controls" aria-label="Feed controls">${icon('settings')}</button></div><div class="feed-explainer">${state.feed==='all'?'Your moments, then interests and people you choose.':'Latest moments first.'} <button data-action="feed-controls">You’re in control ↗</button></div>${state.removed?`<div class="undo-bar">Moment removed. ${btn('Undo','undo-remove','','small')}</div>`:''}<div class="stack">${feed.length?feed.map(postCard).join(''):empty('Make room for something good.','Try another feed, choose an interest or share a moment.',btn('Share a moment','compose','','primary'))}</div><div class="caught-up">${icon('sun')}That’s everything here. Go make a little moment.</div></div>${friendAside()}</div>`;}
function peoplePage(){let list=state.mode==='demo'?PEOPLE:(state.query?state.searchResults:data().people||[]);if(state.mode==='demo'){if(state.people==='friends')list=list.filter(p=>state.demo.friends.includes(p.id));if(state.query)list=list.filter(p=>(p.name+' '+p.handle+' '+p.interest).toLowerCase().includes(state.query.toLowerCase()));}const pending=data().pending||[];return `${pageHeader('Good people. Real connection.','Your people, closer.','A familiar face makes the world feel smaller.',`<a class="btn small" href="#discover">Discover interests ${icon('arrow')}</a>`)}<div class="people-shortcuts"><a class="btn" href="#world">${icon('sun')} My connections in 3D ${icon('arrow')}</a><a href="#space" class="text-link">My Top Mates ↗</a></div><form class="search" data-form="people-search">${icon('search')}<label class="sr-only" for="people-query">${state.mode==='demo'?'Search people or interests':'Search by handle'}</label><input id="people-query" name="query" maxlength="80" value="${esc(state.query)}" placeholder="${state.mode==='demo'?'Search people, interests, a familiar name…':'Find someone by handle…'}"><button type="submit" class="btn small primary">Search</button></form>${pending.length?`<section class="card stack" style="margin-bottom:24px"><h3>Friend requests</h3>${pending.map(p=>`<div class="row">${avatar(memberProfile(p))}<span class="grow">${esc(p.display_name||p.handle)}</span>${btn('Accept','accept',p.friendship_id,'small')}</div>`).join('')}</section>`:''}<div class="filter-row">${[['all',state.mode==='demo'?'Explore people':'Your friends'],['friends','My people']].filter(x=>state.mode==='demo'||x[0]==='all').map(([v,l])=>`<button class="chip ${state.people===v?'on':''}" data-action="people-filter" data-value="${v}">${l}</button>`).join('')}<span class="stamp" style="margin-left:auto">${list.length} ${list.length===1?'person':'people'}</span></div><div class="people-grid">${list.map(p=>{const friend=state.mode==='demo'?state.demo.friends.includes(p.id):(data().people||[]).some(f=>f.id===p.id);const requested=(state.mode==='demo'?state.demo.requests:state.requests||[]).includes(p.id);return `<article class="card person-card"><div class="person-top">${artworkImage(coverArtwork(p,state.mode),{decorative:true})}</div>${avatar(p)}<h3>${esc(p.name)}</h3><span class="handle">@${esc(p.handle)}</span>${sampleLabel(p)}${p.interest?`<div><span class="tag">${esc(p.interest)}</span></div>`:''}<p>${esc(p.bio||'A little space of their own.')}</p><div class="card-bottom">${btn('Visit space','visit',p.handle,'small')}${friend?'<span class="tag">✓ Your people</span>':btn(requested?'Requested':'Connect','connect',p.id,'small primary')}</div></article>`;}).join('')}</div>${!list.length?empty('No familiar face just yet.','Try another name or handle. Your friends will appear here when they connect.'):''}`;}
function talanoa(){if(state.arg)return chatPage();return `${pageHeader('Make a little time together.','Pull up a seat.','The conversation feels better when everyone belongs.',btn(icon('plus')+' New circle','new-circle','','primary'))}<section class="talanoa-banner"><h2>Good conversations.<br>No need for an occasion.</h2>${artworkImage('hero',{className:'talanoa-art',decorative:true})}</section><div class="section-title"><div><span class="eyebrow">Your circles</span><h2>Who are we catching up with?</h2></div>${state.mode==='member'?btn('Join with a code','join-code','','small'):''}</div><div class="circles-grid">${circles().map(c=>`<article class="card circle-card"><div class="circle-cover">${artworkImage(circleArtwork(c),{decorative:true})}</div>${circleBadge(c)}<span class="eyebrow">${state.mode==='demo'?'Sample circle':'Private circle'}</span><h3 style="margin-top:8px">${esc(c.name)}</h3><p>${esc(c.description)}</p><div class="row between"><span class="stamp">${c.members} ${c.members===1?'member':'members'}</span>${btn(c.joined?'Open circle '+icon('arrow'):'Join circle',c.joined?'open-circle':'join-demo',c.id,c.joined?'small':'small primary')}</div></article>`).join('')}</div>${!circles().length?empty('Your first circle starts here.','Give it a name, bring your people, and make it yours.',btn('Start a circle','new-circle','','primary')):''}<p class="muted" style="font-size:11px;margin-top:24px">${state.mode==='demo'?'Sample conversations are fictional. Messages you write here stay on this device.':'Only members of your circle can read its messages. Invitations are shared by you.'}</p>`;}
function chatPage(){const c=circles().find(c=>c.id===state.arg);if(!c)return empty('That circle isn’t here.','Return to your circles to choose one.',`<a class="btn" href="#talanoa">All circles</a>`);if(!c.joined)return empty('There’s a seat for you.','Join this sample circle to try the conversation.',btn('Join circle','join-demo',c.id,'primary'));const messages=data().messages?.[c.id]||[],visible=messages.filter(m=>!state.chatQuery||m.text.toLowerCase().includes(state.chatQuery.toLowerCase())),reply=state.reply?.circle===c.id?state.reply:null;return `${pageHeader('A little time, together.',esc(c.name),'',`<a class="btn small" href="#talanoa">${icon('back')} All circles</a>`)}<div class="chat-layout"><aside class="chat-list"><h3>Your conversations</h3>${circles().filter(c=>c.joined).map(x=>`<button class="${x.id===c.id?'on':''}" data-action="open-circle" data-value="${esc(x.id)}">${circleBadge(x)}<span><b>${esc(x.name)}</b><small>${x.members} ${x.members===1?'member':'members'}</small></span></button>`).join('')}</aside><section class="chat-main"><div class="chat-head row">${circleBadge(c)}<div class="grow"><h2>${esc(c.name)}</h2><small>${c.members} ${c.members===1?'member':'members'} · ${state.mode==='demo'?'Sample conversation':'Private circle'}</small></div>${btn('Details','circle-info',c.id,'small flat')}${state.mode==='member'?btn('Refresh','reload','','small flat'):''}</div><form class="chat-search" data-form="chat-search"><label class="sr-only" for="chat-query">Find in conversation</label>${icon('search')}<input id="chat-query" name="query" maxlength="100" placeholder="Find in this conversation" value="${esc(state.chatQuery)}"><button class="btn small" type="submit">Find</button>${state.chatQuery?btn('Clear','clear-chat-search','','small flat'):''}</form><div class="messages" role="log" aria-label="Circle messages" aria-live="polite">${visible.map(m=>{const mine=m.author===me().id,who=m.person||person(m.author);return `<div class="message ${mine?'mine':''}">${avatar(who)}<div><div class="bubble"><b>${mine?'You':esc(who.name)}</b>${m.reply?`<blockquote>${esc(m.reply.name)}<br>${esc(m.reply.text)}</blockquote>`:''}${esc(m.text)}</div><div class="meta">${timeAgo(m.createdAt)} ${btn('Reply','reply-message',m.id,'message-reply')}${state.mode==='demo'?btn(m.reacted?'♥ 1':'♡','react-message',m.id,'message-reply'):''}</div></div></div>`;}).join('')||`<div class="caught-up">${state.chatQuery?'No matching messages.':'Every good talanoa starts with hello.'}</div>`}</div>${reply?`<div class="reply-strip"><div>Replying to <b>${esc(reply.name)}</b><p>${esc(reply.text)}</p></div>${btn('×','cancel-reply','','small flat')}</div>`:''}<form class="message-form" data-form="message" data-id="${esc(c.id)}"><label for="message-text" class="sr-only">Message to ${esc(c.name)}</label><textarea id="message-text" name="text" maxlength="${state.mode==='member'&&reply?900:1200}" rows="1" placeholder="A little hello…" data-draft="message-${esc(c.id)}" required>${esc(state.drafts['message-'+c.id]||'')}</textarea><button type="submit" class="btn primary" aria-label="Send message">${icon('arrow')}</button></form><div class="chat-note">${state.mode==='demo'?'Sample mode · no message is sent to a real person.':'Private circle · Refresh checks for messages. Search covers the latest 80 loaded messages.'}</div></section></div>`;}
function allTracks(){return [...ORIGINALS,...state.community,...state.uploads];}
function musicPage(){let tracks=state.music==='original'?[...ORIGINALS]:state.music==='community'?state.community:state.music==='local'?state.uploads:allTracks().filter(t=>favorites().includes(t.id));if(state.musicQuery)tracks=tracks.filter(t=>(t.title+' '+t.artist).toLowerCase().includes(state.musicQuery.toLowerCase()));const selected=player.track||ORIGINALS[0];return `${pageHeader('A little soundtrack to your day.','Find your rhythm.','Press play. Stay a little longer.',btn(icon('plus')+' Your music','upload','','small'))}<section class="music-hero">${album(ORIGINALS[0])}<div><span class="eyebrow">Original instrumental sketches · 4 tracks</span><h2>Slow island hours.</h2><p>Four little compositions, made for this space. A pause in the middle of everything.</p>${btn(icon('play')+' Play the sessions','play','lagoon','primary')}</div></section>${visualiserMarkup()}<div class="music-body"><div><div class="filter-row">${[['original','Sota Sessions'],['community','Community mix'],['favorites','Favourites'],['local','Your music']].map(([v,l])=>`<button class="chip ${state.music===v?'on':''}" data-action="music-filter" data-value="${v}">${l}</button>`).join('')}</div><form class="search" data-form="music-search">${icon('search')}<input name="query" aria-label="Search music" placeholder="Find a song…" maxlength="100" value="${esc(state.musicQuery)}"><button type="submit" class="btn small">Find</button></form>${state.music==='community'&&state.communityState==='loading'?'<p class="loading">Opening the community mix…</p>':state.music==='community'&&state.communityState==='error'?`<div class="error">The community playlist couldn’t connect. ${btn('Try again','load-catalogue','','small')}</div>`:''}<div class="track-list">${tracks.map((t,i)=>`<div class="track-row ${player.track?.id===t.id?'on':''}" data-track="${esc(t.id)}"><span class="number">${String(i+1).padStart(2,'0')}</span><button class="track-pick" data-action="play" data-value="${esc(t.id)}" aria-label="Play ${esc(t.title)}">${album(t,true)}<span><strong>${esc(t.title)}</strong><small>${esc(t.artist)}</small></span></button><span class="duration">${t.duration?'0:'+String(t.duration).padStart(2,'0'):''}</span><button class="icon-btn favorite ${favorites().includes(t.id)?'on':''}" data-action="favorite" data-value="${esc(t.id)}" aria-label="${favorites().includes(t.id)?'Unfavourite':'Favourite'} ${esc(t.title)}" aria-pressed="${favorites().includes(t.id)}">${icon('heart')}</button></div>`).join('')}</div>${!tracks.length&&state.communityState!=='loading'?empty(state.music==='favorites'?'Keep a good song close.':state.music==='local'?'Bring your kind of sound.':'No songs found.',state.music==='local'?'Choose an audio file from your device. It plays here without uploading.':'Try another search or explore Sota Sessions.',state.music==='local'?btn('Choose a music file','upload','','primary'):''):''}<p class="muted" style="font-size:10px;margin-top:19px">${state.music==='original'?'Original synthesized instrumentals created for Sota Kece Revised. No recordings or samples.':state.music==='community'?'The existing shared community catalogue. Streaming uses your connection.':state.music==='local'?'Files stay on your device and are available in this tab until you close it.':'Your favourite tracks, kept together on this device.'}</p></div><aside class="stack"><section class="card now-card">${album(selected)}<span class="eyebrow">A little listening room</span><h3 style="margin-top:12px">${esc(selected.title)}</h3><p>${esc(selected.artist)}</p><div class="transport"><button class="icon-btn" data-action="previous" aria-label="Previous track">${icon('previous')}</button><button class="icon-btn main-play" data-action="toggle-play" aria-label="Play or pause music">${icon(audio.paused?'play':'pause')}</button><button class="icon-btn" data-action="next" aria-label="Next track">${icon('next')}</button></div></section><section class="card music-note">${icon('music')}<h3>Good music<br>goes with you.</h3><p>Your soundtrack keeps playing while you catch up, chat or make your space your own.</p></section></aside></div>`;}
function profilePage(){const visitor=state.visitor,own=!state.arg||state.arg===me().handle||state.arg===me().id,p=own?me():visitor||person(state.arg),friends=state.mode==='demo'?PEOPLE.filter(x=>state.demo.friends.includes(x.id)):data().people||[],mine=posts().filter(x=>x.author===p.id).sort((a,b)=>(b.id===p.pinned?1:0)-(a.id===p.pinned?1:0));if(!own&&!visitor)return empty('This space is private.','Connect as friends to see more.');if(visitor?.closed)return empty(p.name+'’s space is private.','Only their friends can see this space.',btn('Ask to connect','connect',p.id,'primary'));return `${!own?`<div class="visitor-note"><a href="#people">← Back to your people</a> · ${state.mode==='demo'?'A fictional sample profile':'A friend’s space'}</div>`:''}<section class="card profile-hero ${own&&currentSkin()?'room-themed':''}" style="${own?skinStyle(currentSkin()):''}"><div class="profile-cover">${own&&currentSkin()?`<img class="room-cover" src="${esc(currentSkin().coverArt)}" alt="${esc(currentSkin().name)} room artwork">`:artworkImage(coverArtwork(p,state.mode),{decorative:true,eager:true})}<span class="profile-caption">${own&&currentSkin()?esc(currentSkin().name):`A little more ${own?'you':'them'}.`}</span></div><div class="profile-main"><div class="row">${avatar(p,'large')}<div class="grow"></div>${own?`<a class="btn small" href="#studio">Design my room</a>`+btn(icon('settings')+' Edit profile','edit-profile','','small'):btn('Find a circle','browse-circles','','small primary')}</div><span class="eyebrow" style="margin-top:17px">${own?'This is your little corner':'A little corner of their world'}</span><h1 tabindex="-1" id="page-title">${esc(p.name)}</h1>${sampleLabel(p)}<span class="muted" style="font-size:12px">@${esc(p.handle)}</span>${p.status?`<span class="profile-status">${esc(p.status)}</span>`:''}<p class="bio">${esc(p.bio||'Good people. Small moments. A place to be yourself.')}</p>${safeLink(p.link)?`<a class="profile-link" href="${esc(safeLink(p.link))}" target="_blank" rel="noopener noreferrer">${esc(new URL(safeLink(p.link)).hostname)} ↗</a>`:''}<div class="profile-stats"><span><b>${own?friends.length:state.mode==='demo'?3:'—'}</b> people</span><span><b>${mine.length}</b> moments</span><span>${state.mode==='demo'?'Sample space':'Your own pace'}</span>${own?'<a class="text-link" href="#world">My world in 3D ↗</a>':''}</div></div></section><div class="profile-content"><div class="stack"><section class="card"><div class="row between"><h3>${own?'Top Mates':'Your people'}</h3>${own?btn('Edit','top-mates','','small flat'):''}</div><div class="mate-grid">${(own?topMates(friends,spacePrefs().mates):friends.slice(0,16)).map(x=>`<button data-action="visit" data-value="${esc(x.handle)}">${avatar(x)}${esc(x.name.split(' ')[0])}</button>`).join('')||'<p class="muted">Your friends will appear here.</p>'}</div></section><section class="card"><span class="eyebrow">The soundtrack</span><button class="profile-song" data-action="play" data-value="${esc(p.song||'lagoon')}">${album(ORIGINALS.find(t=>t.id===p.song)||ORIGINALS[0],true)}<span><strong>${esc((ORIGINALS.find(t=>t.id===p.song)||ORIGINALS[0]).title)}</strong><br><small>Sota Sessions · press play</small></span></button></section><section class="card soft profile-note-card">${own?`<a class="text-link" href="#world">Explore my world in 3D ↗</a>`:''}<p class="profile-note">A space doesn’t have to be big to feel like home.</p></section></div><div><div class="section-title"><h2>${own?'My little moments':'Little moments'}</h2>${own?btn(icon('plus')+' Share','compose','','small'):''}</div><div class="stack">${mine.length?mine.map(postCard).join(''):empty(own?'Start with a little hello.':'A little space to grow.',own?'Share something from your day and make this space feel like you.':'Their moments will appear here.',own?btn('Share my first moment','compose','','primary'):'')}</div></div></div>`;}
function settingsPage(){return `${pageHeader('A space that works for you.','Make yourself comfortable.')}<div class="settings-grid"><section class="card"><h2>Your space</h2><p>A name, a little story and a colour that feels like you. You can change your mind any time.</p>${btn('Edit my space','edit-profile','','primary')}</section><section class="card"><h2>Your privacy</h2><p>${state.mode==='demo'?'This sample community lives on this device. Its people and conversations are fictional. Nothing you post here is sent to another person.':'Your account uses the existing Sota Kece service. Your real community data is fetched only after sign-in and is not saved into the sample community.'}</p>${btn('Read the details','privacy','','small')}</section><section class="card"><h2>${state.mode==='demo'?'Keep your sample work':'Your account'}</h2><p>${state.mode==='demo'?'Download your sample profile, moments and conversations as a JSON file. Your music files are never included.':'Sign out on a shared device. This clears the member pages and any unsent drafts from this tab.'}</p>${state.mode==='demo'?btn(icon('download')+' Download sample data','export-demo','','small'):btn('Sign out','signout','','small')}</section><section class="card"><h2>${state.mode==='demo'?'Ready for your real people?':'A little breathing room'}</h2><p>${state.mode==='demo'?'Sign in to your existing account, or create your own space. Sample activity stays separate from your account.':'Keep only the sound you choose. Music starts only when you press play.'}</p>${state.mode==='demo'?btn('Sign in to my account','auth','','primary'):btn('Pause music','pause','','small')}<div style="margin-top:17px"><a class="text-link" href="#welcome">Back to the welcome page</a></div></section></div>`;}
function render(){worldView?.dispose();worldView=null;visualCleanup?.();visualCleanup=null;const theme=THEMES[me().theme]||THEMES.lagoon;document.documentElement.style.setProperty('--accent',theme.color);document.documentElement.style.setProperty('--paper',theme.paper);document.body.classList.toggle('welcome-mode',state.page==='welcome');let content;if(state.loading)content=pageHeader('A little closer.','Opening your space.')+'<div class="loading"><div class="spinner"></div>Bringing your people together…</div>';else if(state.error)content=empty('A little interruption.',state.error,btn('Try again','reload','','primary'));else content=({home,discover:discoverPage,people:peoplePage,talanoa,music:musicPage,space:profilePage,studio:studioPage,world:worldPage,settings:settingsPage}[state.page]||home)();app.innerHTML=state.page==='welcome'?welcome():shell(content);mountCombined();document.title=(state.page==='welcome'?'Sota Kece — a little closer':(navItems.find(x=>x[0]===state.page)?.[1]||({discover:'Discover',studio:'Room Studio',world:'Your world'}[state.page]||'Settings'))+' · Sota Kece');syncAudio();}
async function loadPage(focus=false){const route=parseRoute(location.hash);Object.assign(state,route);state.error='';state.visitor=null;const run=++state.epoch;state.loading=false;if(state.mode==='demo'){if(state.page==='space'&&state.arg)state.visitor=PEOPLE.find(p=>p.handle===state.arg||p.id===state.arg)||null;render();afterNavigation(focus);return;}if(state.page==='welcome'){render();afterNavigation(focus);return;}state.loading=true;render();try{if(!state.member?.me){const own=await state.service.me();if(run!==state.epoch)return;if(!own){state.loading=false;render();if(!state.recovery)setupDialog();return;}try{const theme=sessionStorage.getItem('sota-revised-theme-'+own.id);if(THEMES[theme])own.theme=theme;}catch{}state.member.me=own;}const s=state.service;
 if(state.page==='home'||state.page==='discover'){const [feed,people,groups]=await Promise.all([s.feed(),s.friends(),s.circles()]);if(run!==state.epoch)return;Object.assign(state.member,{posts:feed,people,circles:groups});state.liked=[];}
 if(state.page==='people'||state.page==='world'){const [people,pending]=await Promise.all([s.friends(),s.pending()]);if(run!==state.epoch)return;Object.assign(state.member,{people,pending});}
 if(state.page==='talanoa'){const groups=await s.circles();if(run!==state.epoch)return;state.member.circles=groups;if(state.arg){const messages=await s.messages(state.arg);if(run!==state.epoch)return;state.member.messages[state.arg]=messages;}}
 if(state.page==='space'||state.page==='studio'){const [feed,people]=await Promise.all([s.feed(),s.friends()]);if(run!==state.epoch)return;Object.assign(state.member,{posts:feed,people});state.liked=[];if(state.arg&&state.arg!==me().handle){const room=await s.room(state.arg);if(run!==state.epoch)return;state.visitor=room?.found?{...memberProfile(room.profile),closed:!room.visible}:null;}}
 }catch(error){if(run===state.epoch)state.error=error.message;}finally{if(run===state.epoch){state.loading=false;render();afterNavigation(focus);}}}
function afterNavigation(focus){if(focus){document.querySelector('#page-title')?.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}const messages=document.querySelector('.messages');if(messages)messages.scrollTop=messages.scrollHeight;if(state.page==='home'&&state.searchTarget){const target=[...document.querySelectorAll('[data-post]')].find(el=>el.dataset.post===state.searchTarget);if(target){target.scrollIntoView({block:'center'});target.classList.add('moment-found');target.setAttribute('tabindex','-1');target.focus({preventScroll:true});}else toast('That moment is no longer in the loaded feed.');state.searchTarget='';}}
function showDialog(title,content,kicker='A little more you'){dialog.innerHTML=`<header class="dialog-head"><div><span class="eyebrow">${kicker}</span><h2 id="dialog-title">${title}</h2></div><button class="icon-btn" data-action="close-dialog" aria-label="Close dialog">${icon('close')}</button></header>${content}`;if(!dialog.open)dialog.showModal();dialog.querySelector('input:not([type=radio]):not([type=hidden]),textarea,select')?.focus();}
function composeDialog(){const kind=state.mode==='demo'?state.postKind:'words';showDialog('A little moment, from you.',`<form class="form-stack" data-form="post"><div class="row">${avatar(me())}<span><b>${esc(me().name)}</b><br><small>${state.mode==='demo'?'Sample community · saved on this device':'Shared with your friends'}</small></span></div>${state.mode==='demo'?`<div class="compose-tabs" role="group" aria-label="Post format">${[['words','✳ Words'],['photo','▧ Photo'],['poll','◔ Poll']].map(([v,l])=>btn(l,'compose-kind',v,kind===v?'on':'')).join('')}</div>`:''}<input type="hidden" name="kind" value="${kind}"><label class="sr-only" for="post-text">Your moment</label><textarea id="post-text" name="text" maxlength="500" placeholder="${kind==='poll'?'Ask something worth talking about…':'Something good, something small, something you…'}" data-draft="post" required>${esc(state.drafts.post||'')}</textarea>${kind==='photo'?`<label class="photo-picker">${state.photo?`<img src="${esc(state.photo.src)}" alt="Selected photo preview">`:`${icon('image')}<strong>A little window into your world.</strong>`}<span>Choose a photo · JPEG, PNG or WebP · up to 8 MB</span><input type="file" name="photoFile" accept="image/jpeg,image/png,image/webp"></label><p class="photo-status" role="status"></p><label>Describe the photo<input name="alt" maxlength="180" value="${esc(state.drafts.photoAlt||'')}" data-draft="photoAlt" placeholder="Help everyone enjoy the moment" required></label><small>Processed on this device. This sample photo is never uploaded.</small>`:kind==='poll'?`<div class="poll-inputs">${[1,2,3,4].map(n=>`<label>Choice ${n}${n>2?' · optional':''}<input name="option${n}" maxlength="80" ${n<3?'required':''} value="${esc(state.drafts['option'+n]||'')}" data-draft="option${n}"></label>`).join('')}</div>`:state.mode==='demo'?`<div class="art-options">${[['','Just words'],['island','Island hours'],['craft','Made by hand'],['music','On repeat']].map(([v,l])=>`<label class="art-option"><input type="radio" name="art" value="${v}" ${v===(state.drafts.postArt||'')?'checked':''}> ${l}</label>`).join('')}</div>`:''}${state.mode==='demo'?`<div class="form-grid"><label>A little interest<select name="topic" data-draft="postTopic"><option value="">Just life</option>${TOPICS.map(t=>`<option value="${t.id}" ${state.drafts.postTopic===t.id?'selected':''}>${t.label}</option>`).join('')}</select></label><label>Replies<select name="replyMode" data-draft="replyMode"><option value="open">Let the conversation grow</option><option value="off" ${state.drafts.replyMode==='off'?'selected':''}>Close replies</option></select></label></div>`:''}<div class="form-error" role="alert"></div><div class="form-foot"><span class="char-count">500 characters · ${state.mode==='demo'?'local sample':'your people'}</span><button class="btn primary" type="submit">Share moment ${icon('arrow')}</button></div></form>`);}
function editProfileDialog(){const p=me();showDialog('Make it feel like you.',`<form class="form-stack" data-form="profile"><div class="form-grid"><label>Your name<input name="name" value="${esc(p.name)}" required maxlength="40"></label>${state.mode==='demo'?`<div class="profile-editor-portrait">${avatar(p,'large')}</div>`:`<label>A little symbol<input name="emoji" value="${esc(p.emoji)}" maxlength="8" aria-label="Profile emoji"></label>`}</div>${state.mode==='demo'?`<fieldset class="identity-options"><legend>Your profile artwork</legend>${IDENTITY_ART.map(([key,label])=>`<label><input type="radio" name="avatarArt" value="${key}" ${identityArtwork(p)===key?'checked':''}>${artworkImage(key,{decorative:true})}<span>${label}</span></label>`).join('')}</fieldset>`:''}<label>A little about you<textarea name="bio" maxlength="400" rows="3">${esc(p.bio)}</textarea></label><div><span class="eyebrow" style="margin-bottom:13px">${state.mode==='demo'?'Your space, your colour':'Theme on this device'}</span><div class="theme-grid">${Object.entries(THEMES).map(([k,t])=>`<label class="theme-pick"><input type="radio" name="theme" value="${k}" ${p.theme===k?'checked':''}><span class="theme-art">${artworkImage(coverArtwork({theme:k,id:'you'}),{decorative:true})}</span>${t.name}</label>`).join('')}</div></div>${state.mode==='demo'?`<label>A little status<input name="status" maxlength="80" value="${esc(p.status||'')}" placeholder="Currently making time for…"></label><div class="form-grid"><label>Your link<input name="link" type="url" maxlength="300" placeholder="https://" value="${esc(p.link||'')}"></label><label>Your soundtrack<select name="song">${ORIGINALS.map(t=>`<option value="${t.id}" ${p.song===t.id?'selected':''}>${esc(t.title)}</option>`).join('')}</select></label></div>`:''}<div class="form-error" role="alert"></div><div class="form-foot"><small>${state.mode==='demo'?'Saved to your sample space.':'Name and bio update your real profile.'}</small><button class="btn primary" type="submit">Save my space</button></div></form>`);}
function authDialog(signup=false){showDialog(signup?'Your people are waiting.':'Welcome back.',`<p class="dialog-copy">${signup?'Create your own space. Sample activity stays separate.':'Sign in to your existing Sota Kece account. Your sample activity stays on this device.'}</p><form class="form-stack" data-form="${signup?'signup':'signin'}">${signup?'<div class="form-grid"><label>Your name<input name="name" autocomplete="name" required maxlength="40"></label><label>Your handle<input name="handle" required pattern="[a-z0-9_]{3,20}" title="3–20 lowercase letters, numbers or underscores" maxlength="20" autocapitalize="none"></label></div>':''}<label>Email<input name="email" type="email" autocomplete="email" required maxlength="254"></label><label>Password<input name="password" type="password" autocomplete="${signup?'new-password':'current-password'}" minlength="${signup?8:1}" required></label>${signup?'<label>Age group<select name="ageBand" required><option value="">Choose your age group</option><option value="teen">16–17</option><option value="adult">18 or over</option></select><small>Sota Kece is for people aged 16 and over. Only your age group is saved.</small></label>':''}<div class="form-error" role="alert"></div><button type="submit" class="btn primary wide">${signup?'Create my account':'Sign in'} ${icon('arrow')}</button>${!signup?'<button type="button" class="text-link" data-action="forgot-password">Forgot your password?</button>':''}<button type="button" class="btn flat" data-action="${signup?'auth':'auth-up'}">${signup?'Already have an account? Sign in':'New here? Create your space'}</button></form>`,'A little closer to home');}
function setupDialog(){showDialog('Finish making your space.',`<p class="dialog-copy">You’re signed in. Choose the name and handle your people will see.</p><form class="form-stack" data-form="setup"><label>Your name<input name="name" required maxlength="40"></label><label>Your handle<input name="handle" pattern="[a-z0-9_]{3,20}" required maxlength="20" autocapitalize="none"></label><label>Age group<select name="ageBand" required><option value="">Choose your age group</option><option value="teen">16–17</option><option value="adult">18 or over</option></select></label><div class="form-error" role="alert"></div><button class="btn primary" type="submit">Make my space</button></form>`);}

// Playback lives outside the changing pages, so navigation never restarts a song.
let player;
player=new Player(audio,syncAudio);
const clock=value=>Number.isFinite(value)?Math.floor(value/60)+':'+String(Math.floor(value%60)).padStart(2,'0'):'0:00';
function syncAudio(){if(!player)return;const box=document.querySelector('#player'),track=player.track;box.hidden=!track;if(!track)return;box.className='player';if(box.dataset.track!==track.id){box.dataset.track=track.id;box.innerHTML=`<div class="player-song">${album(track,true)}<span><strong>${esc(track.title)}</strong><small>${esc(track.artist)}</small></span></div><div class="player-middle"><div class="transport"><button class="icon-btn" data-action="previous" aria-label="Previous track">${icon('previous')}</button><button class="icon-btn main-play" data-action="toggle-play" aria-label="Pause music">${icon('pause')}</button><button class="icon-btn" data-action="next" aria-label="Next track">${icon('next')}</button></div><div class="seek-row"><span data-time>0:00</span><input type="range" min="0" max="24" step="0.1" value="0" data-seek aria-label="Playback position"><span data-duration>0:24</span></div></div><div class="player-extra"><button class="icon-btn" data-action="repeat" aria-label="Repeat track" aria-pressed="false">${icon('repeat')}</button>${icon('volume')}<input type="range" min="0" max="1" step="0.01" value="${audio.volume}" data-volume aria-label="Volume"></div><span class="player-error" role="status"></span>`;}
 document.querySelectorAll('[data-action="toggle-play"]').forEach(b=>{b.innerHTML=icon(audio.paused?'play':'pause');b.setAttribute('aria-label',audio.paused?'Play music':'Pause music');});
 document.querySelectorAll('[data-action="repeat"]').forEach(b=>{b.classList.toggle('on',player.repeat);b.setAttribute('aria-pressed',String(player.repeat));});
 document.querySelectorAll('[data-track]').forEach(row=>{if(row!==box)row.classList.toggle('on',row.dataset.track===track.id);});
 const duration=Number.isFinite(audio.duration)?audio.duration:track.duration||0;
 box.querySelector('[data-time]').textContent=clock(audio.currentTime);box.querySelector('[data-duration]').textContent=clock(duration);
 const seek=box.querySelector('[data-seek]');seek.max=duration;if(document.activeElement!==seek)seek.value=audio.currentTime||0;
 box.querySelector('.player-error').textContent=player.error;
 const now=document.querySelector('.now-card');if(now){now.querySelector('h3').textContent=track.title;now.querySelector('p').textContent=track.artist;const sleeve=now.querySelector('.album-art');if(sleeve.dataset.art!==albumArtwork(track)){sleeve.dataset.art=albumArtwork(track);sleeve.innerHTML=artworkImage(albumArtwork(track),{decorative:true});}}
}
function circleDialog(){showDialog('Make a little circle.',`<form class="form-stack" data-form="circle"><label>Circle name<input name="name" maxlength="40" required placeholder="The Sunday people"></label>${state.mode==='demo'?'<label>A little about this circle<textarea name="description" maxlength="180" placeholder="A place for…"></textarea></label>':''}<p class="dialog-copy">${state.mode==='demo'?'This creates a local sample conversation. No invitations are sent.':'This creates a private circle. Share its invitation code with the people you choose.'}</p><div class="form-error" role="alert"></div><button class="btn primary" type="submit">Create circle</button></form>`);}
function privacyDialog(){showDialog('Your space. Your choice.',`<div class="privacy-copy"><h3>In the sample community</h3><p>The people and conversations are fictional. Your sample profile, moments, favourites and messages are saved in this browser. Nothing is sent to real members. Clear this site’s browser data to remove them.</p><h3>When you sign in</h3><p>Your existing Sota Kece account and its access rules are used. Sharing a moment, connecting or sending a message updates that account. Member content stays separate from sample storage. Sign out on a shared device.</p><h3>Your music</h3><p>Sota Sessions is generated in your browser. Files you choose stay on your device. Community tracks stream from the shared catalogue. Fonts and sign-in load from external services.</p></div>`,'A little clarity');}
async function catalogue(){if(state.communityState==='loading')return;state.communityState='loading';render();try{const response=await fetch('./live/music-playlist.json',{signal:AbortSignal.timeout(10000)});if(!response.ok)throw Error('Playlist unavailable');state.community=validateCatalogue(await response.json());state.communityState='ready';}catch{state.communityState='error';}if(state.page==='music')render();}
function upload(){const input=document.createElement('input');input.type='file';input.accept='audio/*';input.multiple=true;input.addEventListener('change',()=>{let skipped=0;for(const file of input.files){if(state.uploads.length>=12||file.size>50*1024*1024||(!file.type.startsWith('audio/')&&!/\.(mp3|wav|ogg|m4a|aac|flac)$/i.test(file.name))){skipped++;continue;}state.uploads.push({id:'local-'+crypto.randomUUID(),title:file.name.replace(/\.[^.]+$/,''),artist:'From your device · never uploaded',art:'night',url:URL.createObjectURL(file),kind:'local'});}state.music='local';state.musicQuery='';if(state.page!=='music')go('music');else render();if(skipped)toast('Some files were skipped. Choose up to 12 audio files, each under 50 MB.');});input.click();}
function clearMember(){worldView?.dispose();worldView=null;studio.selected='';studio.query='';studio.category='All';state.epoch++;state.service?.owner(null);state.mode='demo';state.member=null;state.drafts={};state.comments.clear();state.searchResults=[];state.query='';state.visitor=null;state.saved=[];state.liked=[];state.favorites=[];state.feed='all';state.error='';state.loading=false;state.requests=[];state.recovery=false;state.localPrefs=preferences();state.photo=null;state.reply=null;state.removed=null;state.postKind='words';state.chatQuery='';state.searchQuery='';state.searchTarget='';dialog.close();}
function setMember(session){if(!session?.user){if(state.mode==='member'){clearMember();loadPage();}return;}if(state.mode==='member'&&state.service?.user?.id===session.user.id)return;clearMember();state.service.owner(session.user);state.mode='member';state.member={me:null,posts:[],people:[],pending:[],circles:[],messages:{}};if(state.page==='welcome')go('home');else loadPage();}
let authReady,authEvent=0;
async function ensureAuth(){if(!authReady)authReady=(async()=>{state.sb=await client();state.service=new Service(state.sb);state.sb.auth.onAuthStateChange((_event,session)=>{const event=++authEvent;if(state.mode==='member'&&state.service.user?.id!==session?.user?.id){clearMember();render();}setTimeout(()=>{if(event===authEvent){setMember(session);if(_event==='PASSWORD_RECOVERY'){state.recovery=true;recoveryDialog();}}},0);});return state.sb;})().catch(()=>{authReady=null;throw Error('Sign-in could not connect. Check your connection and try again.');});return authReady;}
async function signout(){const {error}=await state.sb.auth.signOut();if(error)throw Error(error.message);clearMember();go('welcome');toast('Signed out. Your member pages have been cleared.');}
async function action(name,value,button){
 switch(name){
 case 'studio-pick':if(skinById(value)){studio.selected=value;render();if(window.matchMedia?.('(max-width:760px)').matches)document.querySelector('.studio-preview')?.scrollIntoView({block:'start'});}break;
 case 'studio-filter':studio.category=value;render();break;
 case 'studio-apply':{saveSpace(storage,spaceOwner(),{...spacePrefs(),skin:studio.selected||currentSkin()?.id||'lagoon'});go('space');toast('Your room design is saved on this device.');break;}
 case 'studio-reset':{saveSpace(storage,spaceOwner(),{...spacePrefs(),skin:''});studio.selected='';go('space');toast('Original artwork restored.');break;}
 case 'top-mates':topMatesDialog();break;
 case 'mate-toggle':{const friends=ownFriends(),prefs=spacePrefs(),ids=prefs.mates??friends.slice(0,16).map(p=>p.id);saveSpace(storage,spaceOwner(),{...prefs,mates:toggleMate(ids,value,friends.map(p=>p.id))});topMatesDialog();break;}
 case 'mates-done':dialog.close();render();break;
 case 'compose-kind':if(state.mode!=='demo')break;state.postKind=['words','photo','poll'].includes(value)?value:'words';composeDialog();break;
 case 'interests':interestsDialog();break;
 case 'feed-controls':feedControls();break;
 case 'reset-feed':prefs().hidden=[];prefs().muted=[];persist();dialog.close();render();toast('Hidden moments and muted people restored.');break;
 case 'topic-follow':if(TOPICS.some(t=>t.id===value)){toggle(prefs().interests,value);persist();render();}break;
 case 'post-menu':postMenu(value);break;
 case 'hide-post':toggle(prefs().hidden,value);persist();dialog.close();render();toast('Hidden from your feed. Restore it in Feed controls.');break;
 case 'mute-person':toggle(prefs().muted,value);persist();dialog.close();render();toast('Muted in this feed. Manage this in Feed controls.');break;
 case 'pin-post':{const p=posts().find(p=>p.id===value);if(state.mode!=='demo'||p?.author!=='you')break;state.demo.profile.pinned=state.demo.profile.pinned===value?'':value;persist();dialog.close();render();toast('Your profile highlight has been updated.');break;}
 case 'edit-post':{const p=posts().find(p=>p.id===value);if(state.mode!=='demo'||p?.author!=='you')break;showDialog('A second thought.',`<form data-form="edit-post" data-id="${esc(value)}" class="form-stack"><label>Your moment<textarea name="text" maxlength="500" required>${esc(p.text)}</textarea></label><label>Replies<select name="replyMode"><option value="open">Open</option><option value="off" ${p.replyMode==='off'?'selected':''}>Closed</option></select></label><p class="muted">The photo and poll choices stay as they were shared.</p><div class="form-error" role="alert"></div><button type="submit" class="btn primary">Save changes</button></form>`);break;}
 case 'remove-post':if(state.mode==='demo'){state.removed=removeMoment(state.demo,value);persist();dialog.close();render();toast('Moment removed. Undo is available at Home.');}break;
 case 'undo-remove':if(state.mode==='demo'){restoreMoment(state.demo,state.removed);state.removed=null;persist();render();}break;
 case 'vote':{if(state.mode!=='demo')break;const index=Number(button?.dataset.choice),p=posts().find(p=>p.id===value);vote(p,index);persist();render();break;}
 case 'search':searchDialog();break;
 case 'search-post':dialog.close();state.feed='latest';state.searchTarget=value;go('home');break;
 case 'reply-message':{const m=data().messages?.[state.arg]?.find(m=>m.id===value);if(m){state.reply={circle:state.arg,name:(m.person||person(m.author)).name,text:m.text.slice(0,180)};render();document.querySelector('#message-text')?.focus();}break;}
 case 'cancel-reply':state.reply=null;render();document.querySelector('#message-text')?.focus();break;
 case 'clear-chat-search':state.chatQuery='';render();break;
 case 'react-message':{if(state.mode!=='demo')break;const m=state.demo.messages[state.arg]?.find(m=>m.id===value);if(m){m.reacted=!m.reacted;persist();render();}break;}

 case 'auth':authDialog();ensureAuth().catch(error=>toast(error.message));break;case 'auth-up':authDialog(true);ensureAuth().catch(error=>toast(error.message));break;case 'close-dialog':dialog.close();break;
 case 'compose':composeDialog();break;case 'edit-profile':editProfileDialog();break;case 'reload':await loadPage();break;
 case 'feed-filter':state.feed=value;render();break;case 'people-filter':state.people=value;render();break;
 case 'visit':go('space',value===me().handle||value===me().id?'':value);break;
 case 'comments':state.comments.has(value)?state.comments.delete(value):state.comments.add(value);render();break;
 case 'save-post':toggle(saved(),value);persist();render();break;
 case 'like':if(state.mode==='demo'){toggle(likes(),value);persist();render();}else if(!likes().includes(value)&&!posts().find(p=>p.id===value)?.liked){await state.service.like(value);state.liked.push(value);render();}break;
 case 'connect':if(state.mode==='demo'){if(!state.demo.requests.includes(value)){state.demo.requests.push(value);persist();render();}toast('Sample request saved. No real person was contacted.');}else{if(state.requests?.includes(value))break;await state.service.request(value);(state.requests??=[]).push(value);render();toast('Friend request sent.');}break;
 case 'accept':await state.service.accept(value);await loadPage();toast('Added to your people.');break;
 case 'browse-circles':go('talanoa');break;case 'open-circle':state.chatQuery='';state.reply=null;go('talanoa',value);break;
 case 'join-demo':{const c=state.demo.circles.find(c=>c.id===value);if(c&&!c.joined){c.joined=true;c.members++;persist();}go('talanoa',value);break;}
 case 'new-circle':circleDialog();break;
 case 'join-code':showDialog('There’s a seat for you.',`<form class="form-stack" data-form="join"><label>Invitation code<input name="code" required maxlength="100" autocomplete="off"></label><div class="form-error" role="alert"></div><button class="btn primary" type="submit">Join circle</button></form>`);break;
 case 'circle-info':{const c=circles().find(c=>c.id===value);showDialog(esc(c?.name||'Your circle'),`<p class="dialog-copy">${esc(c?.description||'A private conversation for your people.')}</p>${state.mode==='demo'?'<p>This is a fictional sample circle. Messages stay on this device. Sample members do not send automatic replies.</p>':c?.join_code?`<p>Share this invitation code yourself with someone you want to invite:</p><p class="invite-code">${esc(c.join_code)}</p>`:'<p>Your circle is private. Refresh the conversation to check for new messages.</p>'}`);break;}
 case 'play':{const track=allTracks().find(t=>t.id===value);if(track){player.queue=track.kind==='local'?state.uploads:track.kind==='community'?state.community:[...ORIGINALS];await player.play(track);}break;}
 case 'toggle-play':player.toggle();break;case 'next':player.next(1);break;case 'previous':player.next(-1);break;case 'pause':player.stop();break;
 case 'repeat':player.repeat=!player.repeat;syncAudio();break;
 case 'favorite':toggle(favorites(),value);persist();render();break;
 case 'music-filter':state.music=value;state.musicQuery='';render();if((value==='community'||value==='favorites'&&favorites().some(id=>id.startsWith('community-')))&&state.communityState==='idle')await catalogue();break;
 case 'load-catalogue':await catalogue();break;case 'upload':upload();break;
 case 'forgot-password':showDialog('Find your way back.',`<form class="form-stack" data-form="reset-email"><p class="dialog-copy">We’ll email a secure link to reset your password.</p><label>Email<input name="email" type="email" autocomplete="email" required></label><div class="form-error" role="alert"></div><button class="btn primary" type="submit">Send reset link</button></form>`);break;case 'privacy':privacyDialog();break;
 case 'about-demo':showDialog('A space to try everything.',`<p class="dialog-copy">This is a working preview with fictional people and conversations. The photorealistic portraits and community scenes are AI-generated depictions of Fijians, not photographs of real members or recording artists. Share a moment, join a circle, play a song and make My space your own.</p><p>Your sample changes stay in this browser. Signing in opens your real account, with no sample content copied across.</p>${btn('Make my sample space','edit-profile','','primary')}`,'Welcome to the sample community');break;
 case 'activity':if(state.mode==='demo'){activityDialog();break;} {const pending=state.mode==='demo'?state.demo.requests.length:data().pending?.length||0;showDialog('A little catch-up.',`<p class="dialog-copy">${state.mode==='demo'?`${pending} sample connection ${pending===1?'request':'requests'} saved. Sample people do not reply automatically.`:pending?`${pending} friend ${pending===1?'request is':'requests are'} waiting in People.`:'Open People to check friend requests, or refresh your circles for new messages.'}</p><a class="btn primary" href="#people" data-action="close-dialog">Go to People</a>`);break;}
 case 'signout':await signout();break;
 case 'export-demo':{const url=URL.createObjectURL(new Blob([JSON.stringify(state.demo,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='sota-kece-sample.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Sample data prepared for download.');break;}
 default:throw Error('That action is not available.');
 }
}
document.addEventListener('click',async event=>{const button=event.target.closest('[data-action]');if(!button)return;const {action:name,value=''}=button.dataset,key=name+':'+value;if(state.busy.has(key))return;state.busy.add(key);button.disabled=true;try{await action(name,value,button);}catch(error){toast(error.message||'That did not save. Please try again.');}finally{state.busy.delete(key);button.disabled=false;}});
document.addEventListener('input',event=>{const input=event.target;if(input.dataset.draft)state.drafts[input.dataset.draft]=input.value;if(input.hasAttribute('data-seek'))player.seek(input.value);if(input.hasAttribute('data-volume'))player.setVolume(input.value);});
document.addEventListener('change',event=>{if(event.target.name==='art')state.drafts.postArt=event.target.value;});
dialog.addEventListener('click',event=>{if(event.target===dialog){const rect=dialog.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)dialog.close();}});
document.addEventListener('submit',async event=>{const form=event.target;if(!form.dataset.form)return;event.preventDefault();if(!form.reportValidity())return;const kind=form.dataset.form,key='form:'+kind;if(state.busy.has(key))return;state.busy.add(key);const submit=form.querySelector('[type="submit"]'),values=Object.fromEntries(new FormData(form)),owner=state.service?.user?.id,mode=state.mode;let errorLine=form.querySelector('.form-error');if(errorLine)errorLine.textContent='';if(submit)submit.disabled=true;
 const current=()=>{if(mode!==state.mode||owner!==state.service?.user?.id)throw Error('Your account changed. Please try again.');};
 try{
 if(kind==='studio-search'){studio.query=values.query.trim();render();document.querySelector('[name="query"][data-studio-query]')?.focus();}
 else if(kind==='post'){const text=cleanText(values.text);if(mode==='demo'){if(state.busy.has('photo'))throw Error('Your photo is still being prepared.');createMoment(state.demo,{...values,text,photo:state.photo?{...state.photo,alt:values.alt||''}:null});persist();}else await state.service.post(text);current();delete state.drafts.post;delete state.drafts.postArt;for(const k of ['photoAlt','option1','option2','option3','option4','postTopic','replyMode'])delete state.drafts[k];state.photo=null;state.postKind='words';dialog.close();state.feed='all';if(state.page==='home')await loadPage();else go('home');toast(mode==='demo'?'Your moment is saved in the sample community.':'Your moment is shared.');}
 else if(kind==='interests'){prefs().interests=new FormData(form).getAll('interest').filter(v=>TOPICS.some(t=>t.id===v));persist();dialog.close();render();toast('Your feed, a little more you.');}
 else if(kind==='edit-post'){editMoment(state.demo,form.dataset.id,values);persist();dialog.close();render();}
 else if(kind==='chat-search'){state.chatQuery=values.query.trim();render();}
 else if(kind==='global-search'){state.searchQuery=values.query.trim();searchDialog();}
 else if(kind==='comment'){if(posts().find(p=>p.id===form.dataset.id)?.replyMode==='off')throw Error('Replies are closed for this moment.');addComment(state.demo,form.dataset.id,values.text);delete state.drafts['comment-'+form.dataset.id];persist();render();}
 else if(kind==='message'){const text=cleanText(values.text,1200),circle=form.dataset.id;const reply=state.reply?.circle===circle?state.reply:null;if(mode==='demo'){const message=addMessage(state.demo,circle,text);if(reply)message.reply={name:reply.name,text:reply.text};recordActivity(state.demo,'You added to a circle conversation.');persist();}else await state.service.send(circle,reply?cleanText('Replying to '+reply.name+': '+reply.text+'\n\n'+text,1200):text);current();state.reply=null;delete state.drafts['message-'+circle];if(mode==='member'){const messages=await state.service.messages(circle);current();state.member.messages[circle]=messages;}render();afterNavigation(false);document.querySelector('#message-text')?.focus();}
 else if(kind==='profile'){const next=updateProfile({profile:clone(me())},{...values,emoji:mode==='demo'?me().emoji:values.emoji});if(mode==='demo'){if(values.link&&!safeLink(values.link))throw Error('Use a complete https:// link.');Object.assign(next,{avatarArt:IDENTITY_ART.some(([key])=>key===values.avatarArt)?values.avatarArt:'identity',status:String(values.status||'').trim().slice(0,80),link:safeLink(values.link),song:ORIGINALS.some(t=>t.id===values.song)?values.song:'lagoon'});state.demo.profile=next;recordActivity(state.demo,'You made your space a little more you.');persist();}else{await state.service.saveProfile(next);current();state.member.me=next;try{sessionStorage.setItem('sota-revised-theme-'+owner,next.theme);}catch{}}dialog.close();render();toast('Your space feels a little more you.');}
 else if(kind==='circle'){const name=cleanText(values.name,40);let circle;if(mode==='demo'){circle=newCircle(state.demo,name,values.description);persist();}else{const result=await state.service.createCircle(name);current();circle=Array.isArray(result)?result[0]:result;state.member.circles=await state.service.circles();current();}dialog.close();go('talanoa',String(circle?.id||circle?.crew_id||''));toast('Your circle is ready.');}
 else if(kind==='join'){const joined=await state.service.joinCircle(cleanText(values.code,100));current();if(joined?.error)throw Error(joined.error);if(joined===false||joined?.ok===false)throw Error('That invitation code could not be used. Check it and try again.');dialog.close();go('talanoa');await loadPage();toast('You joined the circle.');}
 else if(kind==='people-search'){state.query=values.query.trim();if(mode==='member'&&state.query){const query=state.query,found=await state.service.search(query);current();if(query!==state.query)return;state.searchResults=found;}render();document.querySelector('#people-query')?.focus();}
 else if(kind==='music-search'){state.musicQuery=values.query.trim();render();document.querySelector('[aria-label="Search music"]')?.focus();}
 else if(kind==='reset-email'){const sb=await ensureAuth();const {error}=await sb.auth.resetPasswordForEmail(values.email.trim(),{redirectTo:new URL('./',location.href).href});if(error)throw Error(error.message);showDialog('Check your inbox.',`<p class="dialog-copy">If an account uses that address, a password reset link will arrive. Follow the link to choose your new password.</p>`);}
 else if(kind==='new-password'){if(values.password!==values.confirm)throw Error('The passwords do not match.');const {error}=await state.sb.auth.updateUser({password:values.password});if(error)throw Error(error.message);state.recovery=false;state.localPrefs=preferences();state.photo=null;state.reply=null;state.removed=null;state.postKind='words';state.chatQuery='';state.searchQuery='';state.searchTarget='';dialog.close();go('home');toast('Your password has been updated.');}
 else if(kind==='signin'||kind==='signup'){const sb=await ensureAuth();let response;if(kind==='signin')response=await sb.auth.signInWithPassword({email:values.email.trim(),password:values.password});else response=await sb.auth.signUp({email:values.email.trim(),password:values.password,options:{data:{display_name:cleanText(values.name,40),requested_handle:values.handle,age_band:values.ageBand},emailRedirectTo:new URL('./',location.href).href}});if(response.error)throw Error(response.error.message);form.querySelector('[name="password"]').value='';if(response.data.session){setMember(response.data.session);dialog.close();go('home');}else showDialog('Check your inbox.',`<p class="dialog-copy">If this address can be registered, a confirmation email will arrive. Follow its link, then sign in here to finish your space.</p>${btn('Back to sign in','auth','','primary')}`);}
 else if(kind==='setup'){if(!/^[a-z0-9_]{3,20}$/.test(values.handle)||!['teen','adult'].includes(values.ageBand))throw Error('Choose a valid handle and age group.');await state.service.setup({...values,name:cleanText(values.name,40)});current();state.member.me=await state.service.me();current();dialog.close();go('home');await loadPage();}
 }catch(error){if(!form.isConnected)toast(error.message);else{if(!errorLine){errorLine=document.createElement('div');errorLine.className='form-error';errorLine.setAttribute('role','alert');form.append(errorLine);}errorLine.textContent=error.message||'That did not save. Please try again.';}}
 finally{state.busy.delete(key);if(submit)submit.disabled=false;}
});
window.addEventListener('hashchange',()=>{if(location.hash==='#main'){document.querySelector('main')?.focus();return;}loadPage(true);});
window.addEventListener('offline',()=>toast('You’re offline. The sample space still works while this tab is open.'));
window.addEventListener('pagehide',event=>{if(!event.persisted){worldView?.dispose();visualCleanup?.();player.destroy();state.uploads.forEach(t=>URL.revokeObjectURL(t.url));}});
loadPage();
if(storage.getItem('sota-revised-auth')||/(?:access_token|code)=/.test(location.hash+location.search))ensureAuth().then(sb=>sb.auth.getSession()).then(({data,error})=>{if(error)throw error;setMember(data.session);}).catch(()=>toast('Your account could not reconnect. You can try signing in again.'));

function recoveryDialog(){showDialog('A fresh start.',`<form class="form-stack" data-form="new-password"><label>New password<input name="password" type="password" minlength="8" autocomplete="new-password" required></label><label>Confirm new password<input name="confirm" type="password" minlength="8" autocomplete="new-password" required></label><div class="form-error" role="alert"></div><button class="btn primary" type="submit">Save new password</button></form>`);}

function circleBadge(c){return `<span class="circle-icon artwork-badge" aria-hidden="true">${artworkImage(circleArtwork(c),{decorative:true})}</span>`;}
function prefs(){return state.mode==='demo'?state.demo.preferences:state.localPrefs;}
function friendIds(){return state.mode==='demo'?state.demo.friends:(data().people||[]).map(p=>p.id);}
function pollMarkup(p){const total=p.poll.votes.reduce((n,v)=>n+v,0);return `<section class="poll" aria-label="Poll"><div class="poll-label">A little question for your people</div>${p.poll.options.map((option,i)=>{const percent=total?Math.round(p.poll.votes[i]/total*100):0;return `<button class="poll-option ${p.poll.choice===i?'chosen':''}" data-action="vote" data-value="${esc(p.id)}" data-choice="${i}" aria-pressed="${p.poll.choice===i}" ${state.mode!=='demo'?'disabled':''}><span class="poll-progress" style="width:${percent}%"></span><span>${p.poll.choice===i?'✓ ':''}${esc(option)}</span><b>${percent}%</b></button>`;}).join('')}<small>${total} ${total===1?'vote':'votes'} · local sample · ${p.poll.choice===null?'choose one':'tap your choice to undo'}</small></section>`;}
function interestsDialog(){showDialog('What brings you a little joy?',`<form class="form-stack" data-form="interests"><p class="dialog-copy">Pick the things you love. For you brings those moments closer. You can change this whenever you like.</p><div class="interest-grid">${TOPICS.map(t=>`<label class="interest-choice ${t.color}"><input type="checkbox" name="interest" value="${t.id}" ${prefs().interests.includes(t.id)?'checked':''}>${artworkImage(topicArtwork(t.id),{decorative:true})}<b>${t.label}</b></label>`).join('')}</div><small>${state.mode==='demo'?'Saved with your sample space.':'Applies to this tab. It only sorts the moments you can already see.'}</small><button class="btn primary" type="submit">Make it my feed ${icon('arrow')}</button></form>`,'Your feed, your choice');}
function feedControls(){showDialog('A little less noise.',`<p class="dialog-copy">For you puts your moments first, then your chosen interests and friends. Within each group, the newest moments come first. Latest always sorts by time.</p><div class="control-row"><div><b>Your interests</b><p>${prefs().interests.length} chosen · no inferred interests</p></div>${btn('Choose','interests','','small')}</div><div class="control-row"><div><b>Hidden & muted</b><p>${prefs().hidden.length} hidden moments · ${prefs().muted.length} muted people</p></div>${btn('Restore all','reset-feed','','small')}</div><p class="muted">${state.mode==='demo'?'These choices stay on this device.':'These choices apply to this tab.'} Muting changes this feed; it does not block someone from contacting you.</p>`,'You’re in control');}
function postMenu(postId){const p=posts().find(p=>p.id===postId);if(!p)return;const own=p.author===me().id;showDialog('Make this moment work for you.',`<div class="menu-actions">${state.mode==='demo'&&own?`${btn('Edit words & replies','edit-post',p.id)}${btn(p.id===me().pinned?'Unpin from My space':'Pin to My space','pin-post',p.id)}${btn('Remove moment · undo available','remove-post',p.id)}`:btn('Hide from my feed','hide-post',p.id)}${!own?btn('Mute this person in my feed','mute-person',p.author):''}${btn('Manage my feed','feed-controls')}</div><p class="muted">${state.mode==='demo'?'Sample controls are saved on this device.':'Feed controls last for this tab. Real posts are managed by the existing community service.'}</p>`);}
function discoverPage(){const topic=TOPICS.find(t=>t.id===state.arg),sample=state.mode==='demo',people=sample?PEOPLE:data().people||[],chosen=topic?people.filter(p=>personTopic(p)===topic.id):people,feed=selectFeed(posts(),prefs(),'latest',{owner:me().id,friends:friendIds(),topic:topic?.id||''});return `${pageHeader('Follow your curiosity.',topic?esc(topic.name):'Find your kind of good.',topic?esc(topic.description):'People, little passions and places to belong.',btn('My interests','interests','','small'))}${topic?`<a class="text-link" href="#discover">← All interests</a>`:`<section class="discovery-lead"><div><span class="eyebrow">You don’t have to be everything.</span><h2>Just find a little<br>of what feels like you.</h2><p>No trending scores. No race to keep up.<br>Choose where your attention goes.</p></div><div class="discovery-orbit" aria-hidden="true">${['music','making','outside','food'].map(k=>artworkImage(k,{decorative:true})).join('')}</div></section>`}<div class="topic-grid">${(topic?[topic]:TOPICS).map(t=>`<article class="topic-card ${t.color}"><a href="#discover/${t.id}"><span class="topic-visual">${artworkImage(topicArtwork(t.id),{decorative:true})}</span><small>${t.label.toUpperCase()}</small><h2>${t.name}</h2><p>${t.description}</p></a><button class="topic-follow ${prefs().interests.includes(t.id)?'on':''}" data-action="topic-follow" data-value="${t.id}" aria-pressed="${prefs().interests.includes(t.id)}">${prefs().interests.includes(t.id)?'✓ Following':'+ Follow interest'}</button></article>`).join('')}</div><div class="section-title"><div><span class="eyebrow">${sample?'Fictional faces, familiar interests':'Your connected people'}</span><h2>A little good company.</h2></div><a class="text-link" href="#people">All people ↗</a></div><div class="discover-people">${chosen.map(p=>`<a class="card discover-person" href="#space/${encodeURIComponent(p.handle)}">${avatar(p,'large')}<h3>${esc(p.name)}</h3>${sampleLabel(p)}<span>${esc(p.interest||'Your community')}</span></a>`).join('')||'<p class="muted">No people match this interest here yet.</p>'}</div><div class="section-title"><h2>${topic?'Around this interest':'Something worth a moment.'}</h2></div><div class="discovery-feed stack">${feed.length?feed.slice(0,12).map(postCard).join(''):empty('A little room to begin.','Share something around this interest.',btn('Share a moment','compose','','primary'))}</div>`;}
function searchDialog(){const result=searchLocal(state.searchQuery,{posts:selectFeed(posts(),prefs(),'latest',{owner:me().id}),people:state.mode==='demo'?PEOPLE:data().people||[],circles:circles()}),total=result.posts.length+result.people.length+result.circles.length;showDialog('Find a little something.',`<form class="search-box" data-form="global-search"><label class="sr-only" for="global-query">Search loaded community</label><input id="global-query" name="query" maxlength="100" value="${esc(state.searchQuery)}" placeholder="A person, a moment, a circle…"><button class="btn primary" type="submit">Search</button></form><p class="muted">Searches the ${state.mode==='demo'?'sample community':'community content loaded in this tab'}. <kbd>Ctrl K</kbd> opens search.</p><div class="search-results">${result.people.length?`<h3>People</h3>${result.people.map(p=>`<a href="#space/${encodeURIComponent(p.handle)}" data-action="close-dialog">${avatar(p)}<span><b>${esc(p.name)}</b><small>@${esc(p.handle)}</small></span>${icon('arrow')}</a>`).join('')}`:''}${result.circles.length?`<h3>Circles</h3>${result.circles.map(c=>`<a href="#talanoa/${encodeURIComponent(c.id)}" data-action="close-dialog">${circleBadge(c)}<b>${esc(c.name)}</b>${icon('arrow')}</a>`).join('')}`:''}${result.posts.length?`<h3>Moments</h3>${result.posts.map(p=>`<button data-action="search-post" data-value="${esc(p.id)}"><span>${esc(p.text.slice(0,120))}</span>${icon('arrow')}</button>`).join('')}`:''}${state.searchQuery&&!total?'<p>No matches here. Try another word.</p>':''}</div>`,'A little closer');}
function activityDialog(){showDialog('Your little trail.',`<p class="dialog-copy">The things you’ve made, shared and added to. Activity on this device; sample people never send automatic replies.</p><div class="activity-list">${state.demo.activity.map(a=>`<div>${icon('sun')}<span>${esc(a.text)}<small>${timeAgo(a.at)}</small></span></div>`).join('')||'<p>Your next little moment starts the story.</p>'}</div><p class="muted">${state.demo.requests.length} sample connection requests saved.</p>`,'A little catch-up');}

document.addEventListener('change',async event=>{const input=event.target;if(input.name!=='photoFile'||!input.files?.[0])return;const epoch=state.epoch,owner=state.mode;state.busy.add('photo');const status=dialog.querySelector('.photo-status');if(status)status.textContent='Preparing your photo on this device…';try{const photo=await preparePhoto(input.files[0]);if(state.epoch!==epoch||state.mode!==owner||state.mode!=='demo')return;state.photo=photo;if(dialog.open&&dialog.querySelector('[data-form="post"]'))composeDialog();}catch(error){if(status?.isConnected)status.textContent=error.message;else toast(error.message);}finally{state.busy.delete('photo');}});
document.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();searchDialog();}if(event.key==='n'&&!dialog.open&&!event.ctrlKey&&!event.metaKey&&!event.altKey&&!/INPUT|TEXTAREA|SELECT/.test(event.target.tagName)){event.preventDefault();composeDialog();}});

function spaceOwner(){return state.mode==='member'?state.service?.user?.id||'unresolved-member':'sample';}
function spacePrefs(){return readSpace(storage,spaceOwner());}
function currentSkin(){return skinById(spacePrefs().skin);}
function ownFriends(){return state.mode==='demo'?PEOPLE.filter(p=>state.demo.friends.includes(p.id)):data().people||[];}
function combinedFeatures(){return `<section class="combined-feature-band"><div><span class="eyebrow">All the things that make it yours</span><h2>A familiar soul.<br>A fresh little world.</h2><p>Island sounds. Your own style. The people and places that bring you home.</p></div><div class="combined-feature-links"><a href="#studio"><b>94 ways to feel at home</b><span>Find your school, island or favourite colour. ↗</span></a><a href="#world"><b>Your world, in 3D</b><span>People, pets and the connections you choose. ↗</span></a><a href="#music"><b>86 reasons to press play</b><span>82 community songs + 4 original Sota Sessions. ↗</span></a></div></section>`;}
function worldPage(){return `${pageHeader('The connections that make you, you.','Your world, connected.','Friends, family, pets and a little piece of home.',`<a class="btn small" href="#people">${icon('back')} Your people</a>`)}<section class="world-intro"><span class="eyebrow">A living little universe</span><p>Turn the world. Move a name. Add someone who matters. This map belongs to you.</p></section><section id="combined-world" aria-label="Your life connections"></section>`;}
function studioPage(){
 const selected=skinById(studio.selected)||currentSkin()||skinById('lagoon');
 const list=SKINS.filter(s=>(studio.category==='All'||s.category===studio.category)&&(!studio.query||[s.name,s.category,s.note,...s.aliases].join(' ').toLowerCase().includes(studio.query.toLowerCase())));
 return `<section class="editorial-studio">${pageHeader('SOTA KECE / ROOM COLLECTION','A space with character.','Considered colours. Original imagery. A room that feels like you.',`<a class="btn small" href="#space">${icon('back')} My space</a>`)}
 <div class="studio-layout"><aside class="studio-preview room-themed" style="${skinStyle(selected)}" aria-label="Selected room preview">
 <div class="studio-cover-wrap"><img class="studio-cover" src="${esc(selected.coverArt)}" alt="${esc(selected.materialName)} artwork"><span class="studio-cover-label">${esc(selected.category)} / ${esc(selected.edition)}</span></div>
 <div class="studio-preview-body">${avatar(me(),'large')}<span class="eyebrow">YOUR ROOM · PREVIEW</span><h2>${esc(me().name)}</h2><p>${esc(me().bio)}</p>
 <div class="studio-chosen" aria-live="polite"><span class="eyebrow">SELECTED DESIGN</span><b>${esc(selected.name)}</b><span>${esc(selected.note)}</span><div class="studio-swatches" aria-label="Room colour palette">${[selected.bg,selected.panel,selected.ink,selected.accent].map(c=>`<span style="background:${esc(c)}" title="${esc(c)}"></span>`).join('')}</div></div>
 <button type="button" class="btn primary" data-action="studio-apply">Use this design ${icon('check')}</button>${btn('Restore original artwork','studio-reset','','flat')}<small>Saved on this device for this account. Your public room stays unchanged.</small></div></aside>
 <section class="studio-library" aria-label="Room design library"><form class="search" data-form="studio-search">${icon('search')}<input data-studio-query name="query" aria-label="Search room designs" value="${esc(studio.query)}" placeholder="Search a design, school or place"><button type="submit" class="btn small">Search</button></form>
 <div class="studio-categories" aria-label="Design categories">${['All',...new Set(SKINS.map(s=>s.category))].map(c=>`<button class="chip ${studio.category===c?'on':''}" data-action="studio-filter" data-value="${esc(c)}" aria-pressed="${studio.category===c}">${esc(c)}</button>`).join('')}</div>
 <div class="row between studio-count"><span>${list.length} ${list.length===1?'design':'designs'} / ${studio.category==='All'?'The complete collection':esc(studio.category)}</span><span>Select to preview</span></div>
 <div class="studio-grid">${list.map(s=>`<button class="skin-card ${selected.id===s.id?'selected':''}" style="${skinStyle(s)}" data-action="studio-pick" data-value="${esc(s.id)}" aria-label="${esc(s.name)} · ${esc(s.category)}" aria-pressed="${selected.id===s.id}"><div class="skin-visual"><img src="${esc(s.coverArt)}" loading="lazy" width="720" height="480" alt=""><span class="skin-edition">${esc(s.edition)}</span></div><span class="skin-caption"><small>${esc(s.category)} / ${esc(s.materialName)}</small><b>${esc(s.name)}</b><span class="skin-palette" aria-hidden="true">${[s.bg,s.panel,s.ink,s.accent].map(c=>`<span style="background:${esc(c)}"></span>`).join('')}<em>Preview ↗</em></span></span>${selected.id===s.id?'<i aria-hidden="true">✓</i>':''}</button>`).join('')||empty('No design found.','Try another word or choose All.')}</div>
 <p class="studio-art-note">Eight original photographic studies, composed into 94 room designs. School, place and music editions are community designs; imagery is atmospheric, not an official portrait of a place or artist.</p></section></div></section>`;
}
function topMatesDialog(){const friends=ownFriends(),chosen=topMates(friends,spacePrefs().mates).map(p=>p.id);showDialog('Keep your people close.',`<p class="dialog-copy">Choose up to 16 connected people for your space. Your selection stays on this device.</p><div class="mates-picker">${friends.map(p=>`<button data-action="mate-toggle" data-value="${esc(p.id)}" aria-pressed="${chosen.includes(p.id)}">${avatar(p)}<span>${esc(p.name)}</span><b>${chosen.includes(p.id)?'✓':'+'}</b></button>`).join('')||'<p>Connect with your people to add them here.</p>'}</div><p class="muted">${chosen.length} / 16 selected</p>${btn('Done','mates-done','','primary')}`,'Your Top Mates');}
function visualiserMarkup(){return `<section class="combined-visuals" aria-label="Live music visualiser"><div class="row between"><div><span class="eyebrow">Sound in colour</span><h2>Your soundtrack, alive.</h2></div><span class="visual-live-label" data-visual-status role="status">Ambient preview · press play</span></div><canvas role="img" aria-label="Music frequency visualisation"></canvas><div class="visual-tools"><label>Visual style<select data-visual-mode><option value="spectrum">Spectrum</option><option value="waveform">Waves</option><option value="halo">Halo</option><option value="ocean">Ocean</option></select></label><button type="button" class="btn small" data-visual-pause aria-pressed="false">Pause visuals</button><span>One song. Everywhere you go.</span></div></section>`;}
function mountCombined(){
 const world=document.querySelector('#combined-world');if(world&&window.SotaLifeConnections){worldView=window.SotaLifeConnections.mount(world,{owner:spaceOwner(),friends:state.mode==='member'?ownFriends().map(p=>({id:p.id,display_name:p.name,handle:p.handle})):[]});}
 const visual=document.querySelector('.combined-visuals');if(visual)visualCleanup=mountVisuals(visual,audio);
 const apply=document.querySelector('[data-default-skin]');if(apply)apply.addEventListener('click',()=>{studio.selected=apply.dataset.defaultSkin;},{once:true});
}
